"""Bundle the reviewed runtime as data for offline/file:// exports."""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
source=(root/'runtime/communication.py').read_text(encoding='utf-8')
(root/'communication-runtime.js').write_text(
    '/* Generated by tools/bundle_communication.py. */\n(function(root){const source='
    +json.dumps(source,ensure_ascii=False)+';if(typeof module!=="undefined")module.exports=source;else root.TDCommunicationRuntime=source;})(typeof window!=="undefined"?window:globalThis);\n',encoding='utf-8')
